//! `splot-capi` - the C ABI of the splot streaming AV2 decoder.
//!
//! The API follows dav1d: open a decoder, send one temporal unit at a time,
//! take pictures, drain at end of stream, close. A picture's plane pointers
//! point into the decoder's own sample storage; no sample is copied. The
//! header is `include/splot.h`, generated by cbindgen.
//!
//! One decoder takes calls from one thread at a time. A picture can be
//! released on any thread.
//!
//! Every `unsafe` block here relies only on the `# Safety` contract of the
//! function it is in: the caller passes null or valid pointers, and each
//! boxed handle goes back to Rust exactly once.
//!
//! Feature tracking: `CAPI-DECODER-ABI`.
//!
//! Licensed under PolyForm Noncommercial 1.0.0; commercial use requires a
//! separate written license from Bartosz Tomczyk.

#![allow(
    unsafe_code,
    reason = "the C ABI dereferences caller pointers; each block states its contract"
)]

use core::ffi::{c_char, c_int, c_void};
use core::num::NonZeroUsize;
use core::ptr;

use splot_core::headers::content_interpretation::DerivedColorInfo;
use splot_decode::{
    BitDepth, DataProps, Decoder, DecoderSettings, FrameDelay, Picture, PictureSamples,
    PixelFormat, PlaneId, PlaneRef, SendStatus, ThreadCount,
};

/// The call succeeded.
pub const SPLOT_OK: c_int = 0;
/// [`splot_send_data`]: the decoder is full; take pictures, then send the
/// same data again. [`splot_get_picture`]: send more data first.
pub const SPLOT_EAGAIN: c_int = -1;
/// [`splot_get_picture`]: the decoder is drained; no picture follows.
pub const SPLOT_EOF: c_int = -2;
/// An argument was null or out of range.
pub const SPLOT_EINVAL: c_int = -3;
/// The bitstream failed to decode, or a resource limit stopped it. The
/// decoder takes no more data; close it.
pub const SPLOT_EDECODE: c_int = -4;
/// The decoder takes no more data: it is draining, or it failed earlier.
pub const SPLOT_ESTATE: c_int = -5;

/// An open decoder.
pub struct SplotDecoder {
    decoder: Decoder,
    drained: bool,
}

/// How [`splot_open`] sets up a decoder. Fill it with
/// [`splot_default_settings`] first.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct SplotSettings {
    /// Worker threads; 0 picks one per logical core.
    pub n_threads: u32,
    /// Frames decoded in parallel; 0 picks a value from `n_threads`. 1 is
    /// lowest latency.
    pub max_frame_delay: u32,
    /// Reserved; keep zero.
    pub reserved: [u8; 32],
}

/// Caller data that goes with one temporal unit to the pictures it codes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct SplotDataProps {
    /// Presentation timestamp, in the caller's time base.
    pub pts: i64,
    /// Duration, in the caller's time base.
    pub duration: i64,
    /// An opaque caller value.
    pub user_data: u64,
}

/// Chroma layout of a picture.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SplotPixelLayout {
    /// Luma only.
    I400 = 0,
    /// 4:2:0.
    I420 = 1,
    /// 4:2:2.
    I422 = 2,
    /// 4:4:4.
    I444 = 3,
}

/// Color description of a picture, from AV2 § 5.15 content interpretation.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct SplotColor {
    /// Color primaries code point.
    pub primaries: u8,
    /// Transfer characteristics code point.
    pub transfer: u8,
    /// Matrix coefficients code point.
    pub matrix: u8,
    /// 1 for full range, 0 for limited range.
    pub full_range: u8,
}

/// A decoded picture. Valid from [`splot_get_picture`] until
/// [`splot_picture_unref`].
#[repr(C)]
#[derive(Debug)]
pub struct SplotPicture {
    /// Y, U and V planes at their first stored sample, 64-byte aligned.
    /// The visible area starts `crop_top` rows and `crop_left` samples in
    /// (both shifted right by the chroma subsampling for U and V). 8-bit
    /// pictures hold one byte per sample, 10-bit pictures one `uint16_t` per
    /// sample in the low bits. U and V are null for [`SplotPixelLayout::I400`].
    pub data: [*const c_void; 3],
    /// Bytes from one row to the next, for each plane; a multiple of 64.
    pub stride: [isize; 3],
    /// Visible width in luma samples.
    pub width: u32,
    /// Visible height in luma samples.
    pub height: u32,
    /// Luma samples between the left of `data` and the visible area.
    pub crop_left: u32,
    /// Luma rows between the top of `data` and the visible area.
    pub crop_top: u32,
    /// Bits per sample: 8 or 10.
    pub bit_depth: u32,
    /// Chroma layout.
    pub layout: SplotPixelLayout,
    /// Color description.
    pub color: SplotColor,
    /// The caller data of the unit that coded or showed this picture.
    pub props: SplotDataProps,
    /// Reserved.
    pub reserved: [usize; 4],
    /// The decoder's handle on the samples; do not touch.
    pub internal: *mut c_void,
}

/// The library version as a NUL-terminated string.
#[unsafe(no_mangle)]
pub extern "C" fn splot_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// Fills `settings` with the defaults.
///
/// # Safety
/// `settings` is null or points to writable memory for one [`SplotSettings`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_default_settings(settings: *mut SplotSettings) {
    if let Some(settings) = unsafe { settings.as_mut() } {
        *settings = SplotSettings {
            n_threads: 0,
            max_frame_delay: 0,
            reserved: [0; 32],
        };
    }
}

/// Opens a decoder and stores it in `*out`.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EINVAL`] for a null argument or nonzero
/// reserved bytes, or [`SPLOT_EDECODE`] when the worker pool cannot start.
///
/// # Safety
/// `out` is null or writable; `settings` is null or points to a
/// [`SplotSettings`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_open(
    out: *mut *mut SplotDecoder,
    settings: *const SplotSettings,
) -> c_int {
    let (Some(out), Some(settings)) = (unsafe { out.as_mut() }, unsafe { settings.as_ref() })
    else {
        return SPLOT_EINVAL;
    };
    *out = ptr::null_mut();
    if settings.reserved.iter().any(|&byte| byte != 0) {
        return SPLOT_EINVAL;
    }
    let count = |value: u32| NonZeroUsize::new(value as usize);
    let settings = DecoderSettings::default()
        .with_threads(count(settings.n_threads).map_or(ThreadCount::Auto, ThreadCount::Fixed))
        .with_frame_delay(
            count(settings.max_frame_delay)
                .map_or(FrameDelay::Auto, |depth| FrameDelay::from(depth.get())),
        );
    match Decoder::new(settings) {
        Ok(decoder) => {
            *out = Box::into_raw(Box::new(SplotDecoder {
                decoder,
                drained: false,
            }));
            SPLOT_OK
        }
        Err(_) => SPLOT_EDECODE,
    }
}

/// Sends one whole temporal unit of `size` bytes. The decoder copies it.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EAGAIN`] when the decoder is full,
/// [`SPLOT_EINVAL`], [`SPLOT_EDECODE`] or [`SPLOT_ESTATE`].
///
/// # Safety
/// `decoder` is null or came from [`splot_open`]; `data` points to `size`
/// readable bytes (it may be null when `size` is 0); `props` is null or
/// points to a [`SplotDataProps`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_send_data(
    decoder: *mut SplotDecoder,
    data: *const u8,
    size: usize,
    props: *const SplotDataProps,
) -> c_int {
    let Some(SplotDecoder { decoder, .. }) = (unsafe { decoder.as_mut() }) else {
        return SPLOT_EINVAL;
    };
    let data: &[u8] = match (data.is_null(), size) {
        (_, 0) => &[],
        (true, _) => return SPLOT_EINVAL,
        (false, size) => unsafe { core::slice::from_raw_parts(data, size) },
    };
    let props = unsafe { props.as_ref() }.copied().unwrap_or_default();
    let props = DataProps::default()
        .with_pts(props.pts)
        .with_duration(props.duration)
        .with_user_data(props.user_data);
    match decoder.send_data(data, props) {
        Ok(SendStatus::Accepted) => SPLOT_OK,
        Ok(SendStatus::Full) => SPLOT_EAGAIN,
        Err(error) => error_code(&error),
    }
}

/// Ends the input; [`splot_get_picture`] then returns the remaining pictures
/// and [`SPLOT_EOF`].
///
/// # Safety
/// `decoder` is null or came from [`splot_open`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_drain(decoder: *mut SplotDecoder) {
    if let Some(SplotDecoder { decoder, drained }) = unsafe { decoder.as_mut() } {
        decoder.drain();
        *drained = true;
    }
}

/// Takes the next picture in display order into `*out`.
///
/// Returns [`SPLOT_OK`], [`SPLOT_EAGAIN`] when more data is needed,
/// [`SPLOT_EOF`] after the last picture of a drained decoder,
/// [`SPLOT_EINVAL`] or [`SPLOT_EDECODE`]. On any result but [`SPLOT_OK`],
/// `*out` is zeroed.
///
/// # Safety
/// `decoder` is null or came from [`splot_open`]; `out` is null or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_get_picture(
    decoder: *mut SplotDecoder,
    out: *mut SplotPicture,
) -> c_int {
    let (Some(SplotDecoder { decoder, drained }), Some(out)) =
        (unsafe { decoder.as_mut() }, unsafe { out.as_mut() })
    else {
        return SPLOT_EINVAL;
    };
    *out = empty_picture();
    match decoder.get_picture() {
        Ok(Some(picture)) => {
            *out = c_picture(picture);
            SPLOT_OK
        }
        Ok(None) if *drained => SPLOT_EOF,
        Ok(None) => SPLOT_EAGAIN,
        Err(error) => error_code(&error),
    }
}

/// Releases a picture from [`splot_get_picture`] and zeroes it.
///
/// # Safety
/// `picture` is null or points to a picture from [`splot_get_picture`] that
/// was not released yet, or to a zeroed picture.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_picture_unref(picture: *mut SplotPicture) {
    let Some(picture) = (unsafe { picture.as_mut() }) else {
        return;
    };
    let internal = core::mem::replace(picture, empty_picture()).internal;
    if !internal.is_null() {
        drop(unsafe { Box::from_raw(internal.cast::<Picture>()) });
    }
}

/// Closes a decoder and sets `*decoder` to null. Pictures already taken stay
/// valid until released.
///
/// # Safety
/// `decoder` is null or points to null or to a decoder from [`splot_open`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn splot_close(decoder: *mut *mut SplotDecoder) {
    let Some(decoder) = (unsafe { decoder.as_mut() }) else {
        return;
    };
    let owned = core::mem::replace(decoder, ptr::null_mut());
    if !owned.is_null() {
        drop(unsafe { Box::from_raw(owned) });
    }
}

fn error_code(error: &splot_decode::DecodeError) -> c_int {
    match error {
        splot_decode::DecodeError::State { .. } => SPLOT_ESTATE,
        _ => SPLOT_EDECODE,
    }
}

const fn empty_picture() -> SplotPicture {
    SplotPicture {
        data: [ptr::null(); 3],
        stride: [0; 3],
        width: 0,
        height: 0,
        crop_left: 0,
        crop_top: 0,
        bit_depth: 0,
        layout: SplotPixelLayout::I400,
        color: SplotColor {
            primaries: 0,
            transfer: 0,
            matrix: 0,
            full_range: 0,
        },
        props: SplotDataProps {
            pts: 0,
            duration: 0,
            user_data: 0,
        },
        reserved: [0; 4],
        internal: ptr::null_mut(),
    }
}

fn c_picture(picture: Picture) -> SplotPicture {
    let mut out = empty_picture();
    for (index, plane) in [PlaneId::Y, PlaneId::U, PlaneId::V].into_iter().enumerate() {
        (out.data[index], out.stride[index]) = match picture.plane(plane) {
            Some(PictureSamples::Eight(plane)) => storage_origin(plane),
            Some(PictureSamples::Ten(plane)) => storage_origin(plane),
            None => (ptr::null(), 0),
        };
    }
    let color = picture
        .content_interpretation()
        .map_or(DerivedColorInfo::UNSPECIFIED, |content| {
            content.derived_color()
        });
    let props = picture.props();
    out.width = picture.width() as u32;
    out.height = picture.height() as u32;
    let crop = match picture.plane(PlaneId::Y) {
        Some(PictureSamples::Eight(luma)) => Some(luma.visible_rect()),
        Some(PictureSamples::Ten(luma)) => Some(luma.visible_rect()),
        None => None,
    };
    out.crop_left = crop.map_or(0, |crop| crop.x() as u32);
    out.crop_top = crop.map_or(0, |crop| crop.y() as u32);
    out.bit_depth = match picture.bit_depth() {
        BitDepth::Eight => 8,
        BitDepth::Ten => 10,
    };
    out.layout = match picture.pixel_format() {
        PixelFormat::Monochrome => SplotPixelLayout::I400,
        PixelFormat::Yuv420 => SplotPixelLayout::I420,
        PixelFormat::Yuv422 => SplotPixelLayout::I422,
        PixelFormat::Yuv444 => SplotPixelLayout::I444,
    };
    out.color = SplotColor {
        primaries: color.primaries.0,
        transfer: color.primaries.1,
        matrix: color.primaries.2,
        full_range: u8::from(color.full_range),
    };
    out.props = SplotDataProps {
        pts: props.pts,
        duration: props.duration,
        user_data: props.user_data,
    };
    out.internal = Box::into_raw(Box::new(picture)).cast();
    out
}

/// The address of `plane`'s first stored sample and its stride in bytes.
fn storage_origin<T: splot_decode::ReconSample>(plane: PlaneRef<'_, T>) -> (*const c_void, isize) {
    (
        plane.samples().as_ptr().cast(),
        (plane.stride_samples() * size_of::<T>()) as isize,
    )
}
